import{_ as r,a0 as n,w as p,s as c,ao as a,I as d,x as t,a1 as s,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"你或許不知道的實用 GNOME Shell 快捷鍵 | LCTT x X-CMD","titleTemplate":false,"description":"你或許不知道的實用 GNOME Shell 快捷鍵 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"你或許不知道的實用 GNOME Shell 快捷鍵 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"你或許不知道的實用 GNOME Shell 快捷鍵 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171120 Useful GNOME Shell Keyboard Shortcuts You Might Not Know About","title":"你或許不知道的實用 GNOME Shell 快捷鍵","tag":"201712","desc":""},"relativePath":"201712/20171120 Useful GNOME Shell Keyboard Shortcuts You Might Not Know About.md","filePath":"[post].md"}'),h={name:"201712/20171120 Useful GNOME Shell Keyboard Shortcuts You Might Not Know About.md"};function u(i,e,m,g,f,S){const o=n("Link");return p(),c("div",null,[e[16]||(e[16]=a('<h1 id="你或許不知道的實用-gnome-shell-快捷鍵" tabindex="-1">你或許不知道的實用 GNOME Shell 快捷鍵 <a class="header-anchor" href="#你或許不知道的實用-gnome-shell-快捷鍵" aria-label="Permalink to “你或許不知道的實用 GNOME Shell 快捷鍵”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-00-featured.jpg" alt=""></p><p>由於 Ubuntu 在 17.10 發行版本中轉移到了 GNOME Shell，許多用户可能對那些實用的快捷鍵以及創建自己的快捷鍵感興趣。這篇文章就是介紹這兩方面的。</p><h3 id="已有的便捷的-gnome-shell-快捷鍵" tabindex="-1">已有的便捷的 GNOME Shell 快捷鍵 <a class="header-anchor" href="#已有的便捷的-gnome-shell-快捷鍵" aria-label="Permalink to “已有的便捷的 GNOME Shell 快捷鍵”">​</a></h3><p>如果你希望 GNOME 有成百上千種快捷鍵，你會失望地發現，情況並非如此。快捷鍵的列表不會太長，而且並不是全部都對你有用，但仍然會有許多快捷鍵可以用得上的。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-01-settings.jpg" alt="gnome-shortcuts-01-settings" title="gnome-shortcuts-01-settings"></p><p>可以通過菜單“設置 -&gt; 設備 -&gt; 鍵盤”訪問快捷方式列表。以下是一些不太流行但實用的快捷方式。</p><ul><li><code>Ctrl</code> + <code>Alt</code> + <code>T</code> - 這是一個用來啓動終端的快捷鍵組合，你可以在 GNOME 的任何地方使用它。</li></ul><p>我個人經常使用的兩個快捷鍵是：</p><ul><li><code>Alt</code> + <code>F4</code> - 關閉最頂層端口</li><li><code>Alt</code> + <code>F8</code> - 調整窗口大小</li></ul><p>大多數人都知道如何用 <code>Alt</code> + <code>Tab</code> 在打開的應用程序窗口之間，但是你可能不知道可以使用 <code>Alt</code> + <code>Shift</code> + <code>Tab</code> 在應用程序窗口之間進行反方向切換。</p><p>在切換窗口界面時，另一個有用的組合鍵是 <code>Alt</code> + <code>~</code> （<code>tab</code> 鍵上面的一個鍵）。</p><p>要是你想顯示活動概覽，你可以用快捷鍵 <code>Alt</code> + <code>F1</code>。</p><p>有很多跟工作台有關的快捷鍵。如果你像我那樣不經常使用多個工作台的話，這些快捷鍵對來説是沒用的。儘管如此，以下幾個快捷鍵還是值得留意的：</p><ul><li><code>Super</code> + <code>PageUp</code> （或者 <code>PageDown</code> ）移動到上方或下方的工作台</li><li><code>Ctrl</code> + <code>Alt</code> + <code>Left</code> （或 <code>Right</code> ）移動到左側或右側的工作台</li></ul><p>如果在這些快捷鍵中加上 <code>Shift</code> ，例如 <code>Shift</code> + <code>Ctrl</code> + <code>Alt</code> + <code>Left</code>，則可以把當前窗口移動到其他工作區。</p><p>另一個我最喜歡是輔助功能中的調整文字大小的快捷鍵。你可以用 <code>Ctrl</code> + <code>+</code> （或 <code>Ctrl</code> + <code>-</code> ）快速縮放字體大小。在某些情況下，這個快捷鍵可能默認是禁用的，所以在嘗試之前請先檢查一下。</p>',17)),d("p",null,[e[1]||(e[1]=t("上述是一些鮮為人知但是十分實用的鍵盤快捷鍵。如果你想知道更多實用的快捷鍵，可以查看",-1)),s(o,{href:"https://wiki.gnome.org/Projects/GnomeShell/CheatSheet"},{default:l(()=>[...e[0]||(e[0]=[t("官方 GNOME Shell 快捷鍵列表",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))]),e[17]||(e[17]=a('<h3 id="如何創建自己的-gnome-shell-快捷鍵" tabindex="-1">如何創建自己的 GNOME Shell 快捷鍵 <a class="header-anchor" href="#如何創建自己的-gnome-shell-快捷鍵" aria-label="Permalink to “如何創建自己的 GNOME Shell 快捷鍵”">​</a></h3><p>如果默認的快捷鍵不符合您的喜好，可以更改它們或創建新的快捷鍵。你同樣可以通過菜單“設置 -&gt; 設備 -&gt; 鍵盤“完成這些操作。當你選擇想更改的快捷鍵條目時，下面的對話框就會彈出。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-02-change-shortcut.png" alt="gnome-shortcuts-02-change-shortcut" title="gnome-shortcuts-02-change-shortcut"></p><p>輸入你想要的鍵盤快捷鍵組合。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-03-set-shortcut.png" alt="gnome-shortcuts-03-set-shortcut" title="gnome-shortcuts-03-set-shortcut"></p><p>如果這個快捷鍵已經被使用，你會得到一個消息。如果沒有，只需點擊設置，就完成了。</p><p>如果要添加新快捷鍵而不是更改現有快捷鍵，請向下滾動，直到看到 “+” 標誌，單擊它，在出現的對話框中輸入新鍵盤快捷鍵的名稱和快捷鍵組合。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/gnome-shortcuts-04-add-custom-shortcut.png" alt="gnome-shortcuts-04-add-custom-shortcut" title="gnome-shortcuts-04-add-custom-shortcut"></p><p>GNOME 默認情況下並沒有提供大量的 shell 快捷鍵，上面列出的是一些比較實用的快捷鍵。如果這些快捷鍵對你來説不夠，你可以隨時創建自己的快捷鍵。</p><hr>',10)),d("p",null,[e[4]||(e[4]=t("via: ",-1)),s(o,{href:"https://www.maketecheasier.com/gnome-shell-keyboard-shortcuts/"},{default:l(()=>[...e[3]||(e[3]=[t("https://www.maketecheasier.com/gnome-shell-keyboard-shortcuts/",-1)])]),_:1})]),d("p",null,[e[8]||(e[8]=t("作者：",-1)),s(o,{href:"https://www.maketecheasier.com/author/adaivanoff/"},{default:l(()=>[...e[5]||(e[5]=[t("Ada Ivanova",-1)])]),_:1}),e[9]||(e[9]=t(" 譯者：",-1)),s(o,{href:"https://github.com/imquanquan"},{default:l(()=>[...e[6]||(e[6]=[t("imquanquan",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),s(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),d("p",null,[e[13]||(e[13]=t("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創編譯，",-1)),s(o,{href:"https://linux.cn/"},{default:l(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const M=r(h,[["render",u]]);export{N as __pageData,M as default};
